const VERSION='shogi-shell-v6';
const ROOT=new URL('./',self.location).href;
const SHELL=["./", "./app.js", "./teacher.js", "./teacher-analysis.js", "./coach-analysis.js", "./coach-ui.js", "./core.js", "./credits.html", "./engine-worker.js", "./engine.js", "./icon.svg", "./index.html", "./manifest.webmanifest", "./style.css", "./tutor-worker.js", "./tutor.js", "./vendor/tsshogi/LICENSE", "./vendor/tsshogi/board.js", "./vendor/tsshogi/color.js", "./vendor/tsshogi/csa.js", "./vendor/tsshogi/detect.js", "./vendor/tsshogi/direction.js", "./vendor/tsshogi/errors.js", "./vendor/tsshogi/hand.js", "./vendor/tsshogi/helpers/string.js", "./vendor/tsshogi/helpers/time.js", "./vendor/tsshogi/index.js", "./vendor/tsshogi/jkf.js", "./vendor/tsshogi/kakinoki.js", "./vendor/tsshogi/move.js", "./vendor/tsshogi/piece.js", "./vendor/tsshogi/position.js", "./vendor/tsshogi/record.js", "./vendor/tsshogi/square.js", "./vendor/tsshogi/text.js", "./vendor/yaneuraou/Copying.txt", "./vendor/yaneuraou/yaneuraou.data", "./vendor/yaneuraou/yaneuraou.js", "./vendor/yaneuraou/yaneuraou.wasm", "./vendor/yaneuraou/yaneuraou.worker.js"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(VERSION).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('shogi-shell-')&&k!==VERSION).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||!event.request.url.startsWith(ROOT))return;event.respondWith((async()=>{const cache=await caches.open(VERSION);let response;try{response=await fetch(event.request);if(response.ok&&!response.redirected)await cache.put(event.request,response.clone());}catch{response=await cache.match(event.request);}if(!response)return new Response('Offline: open this page once while connected.',{status:503});if(response.type==='opaque'||response.redirected)return response;const headers=new Headers(response.headers);headers.set('Cross-Origin-Opener-Policy','same-origin');headers.set('Cross-Origin-Embedder-Policy','require-corp');return new Response(response.body,{status:response.status,statusText:response.statusText,headers});})());});
